CREATE POLICY "vcat read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'vehicle-catalog');
CREATE POLICY "vcat admin insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'vehicle-catalog' AND (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'super_admin')));
CREATE POLICY "vcat admin update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'vehicle-catalog' AND (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'super_admin')));
CREATE POLICY "vcat admin delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'vehicle-catalog' AND (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'super_admin')));